change_filament_gcode:
;===== BMCU tool change ===========
; Change Tool[previous_extruder] -> Tool[next_extruder] (layer [layer_num])
; max_layer_z [max_layer_z]
; max_print_height [max_print_height]
; print_sequence [print_sequence]

{
local move_z = 1.5;
local max_speed_toolchange = 350.0;
local preheat_next_extruder = true;
position[2] = position[2] + 2.0;
local speed_toolchange = max_speed_toolchange;

if travel_speed < max_speed_toolchange then
      speed_toolchange = travel_speed;
endif

if print_sequence == "by object" then

    if max_layer_z < ((max_print_height - z_offset) - 2) then
        move_z = z_offset + min(((max_layer_z - z_offset) + 2), max_print_height);
    endif

endif

"G91
G1 Z" + move_z + " F600
G90
";
"G1 F" + (speed_toolchange * 60) + "
";

if previous_extruder < 4 then
      "MOVE_TO_XY_IDLE_POSITION_EXTRUDER
";
endif
"M400
";

if preheat_next_extruder and not((layer_num < 0) and (next_extruder == initial_tool)) then
      "
";
      "; nonblocking preheat for Tool" + next_extruder + "
";
      if layer_num == 0 then
            "M104 S" + first_layer_temperature[next_extruder] + " T" + next_extruder + "
";
      else
            "M104 S" + temperature[next_extruder] + " T" + next_extruder + "
";
      endif
endif
"BMCU_TOOL_CHANGE TOOL=" + next_extruder + "
";
if filament_type[next_extruder] == "PVA" then
"SET_VELOCITY_LIMIT ACCEL=3000
";
else
endif
if previous_extruder != next_extruder and initial_extruder != next_extruder then
"BMCU_PRINT_PREEXTRUDE TOOL=" + next_extruder + "
";
endif
"G90
";
}

machine_end_gcode:
;===== Snapmaker U1 end sequence =====================
; layer [layer_num]
; max_layer_z [max_layer_z]
; print_sequence [print_sequence]

{if print_sequence == "by object"}
{
local move_z = max_print_height;

if max_layer_z < ((max_print_height - z_offset) - 2) then
    move_z = z_offset + min(((max_layer_z - z_offset) + 2), max_print_height);
endif
}

G91
G1 X2 Y2 Z1 F24000
G90
G1 Z{move_z} F600
{endif}

BMCU_PRINT_END MODE=AUTO CLEAR=0
PRINT_END
TIMELAPSE_STOP
